import random

def is_even(x):
    return x % 2 == 0

# Test a range of integers including negatives
test_values = list(range(-10, 11)) + [random.randint(-1000, 1000) for _ in range(20)]
all_even = True
for n in test_values:
    product = n * (n + 1)
    if not is_even(product):
        print(f"Counterexample: n={n}, product={product}")
        all_even = False
        break
if all_even:
    print("All tested products are even.")
else:
    print("Found a counterexample.")
